def render_page(screen, title, **values):
    response = app.make_response(
        render_template_string(PAGE, screen=screen, title=title, **values)
    )
    response.headers["Cache-Control"] = "no-store"
    return response


def make_qr(link):
    image = io.BytesIO()
    qrcode.make(link, image_factory=SvgPathFillImage).save(image)
    return "data:image/svg+xml;base64," + base64.b64encode(image.getvalue()).decode()


def get_team(room_id, token):
    room = rooms.get(room_id)
    if room is None or token not in room["teams"]:
        abort(404, "This room or invite is no longer available.")
    return room, room["teams"][token]


def stage_url(stage, room_id, token):
    endpoints = {"lobby": "lobby", "naming": "name_page", "reveal": "reveal"}
    return url_for(endpoints[stage], room_id=room_id, token=token)


@app.get("/")
@app.get("/index.html")
def home():
    return send_from_directory(app.root_path, "index.html")


@app.route("/game.html", methods=["GET", "POST"])
def setup():
    mode = request.args.get("mode", "quiz")
    if mode not in GAME_NAMES:
        abort(404)

    if request.method == "GET":
        return render_page("setup", f"{GAME_NAMES[mode]} Team Setup", mode=mode)

    count = 2 if mode == "xo" else request.form.get("count", type=int)
    if count is None or not 1 <= count <= 6:
        abort(400, "Choose 1 to 6 teams.")

    room_id = secrets.token_urlsafe(16)
    host_token = secrets.token_urlsafe(16)
    teams = {host_token: 1}
    for number in range(2, count + 1):
        teams[secrets.token_urlsafe(16)] = number

    with room_lock:
        rooms[room_id] = {
            "mode": mode,
            "teams": teams,
            "joined": {1},
            "names": {},
            "stage": "lobby",
        }

    return redirect(stage_url("lobby", room_id, host_token), code=303)


@app.route("/room/<room_id>/<token>", methods=["GET", "POST"])
def lobby(room_id, token):
    error = None

    with room_lock:
        room, number = get_team(room_id, token)
        count = len(room["teams"])

        if request.method == "POST":
            action = request.form.get("action")

            if action == "join" and room["stage"] == "lobby":
                room["joined"].add(number)
            elif action == "start":
                if number != 1:
                    abort(403)
                if room["stage"] == "lobby":
                    if len(room["joined"]) == count:
                        if room["mode"] == "guess":
                            room["variant"] = guess_variant()
                            room["history"] = transfer_history()
                            if room["variant"] == "mystery":
                                room["mystery_seen"] = request.cookies.get("mystery_seen", "").split(".")
                        if room["mode"] == "xo":
                            room["xo_settings"] = xo_settings(team=True)
                        room["stage"] = "naming"
                    else:
                        error = "Wait for all teams to join."

            if error is None:
                return redirect(stage_url(room["stage"], room_id, token), code=303)

        if number not in room["joined"]:
            return render_page("join", f"Team {number}", number=number)

        if room["stage"] != "lobby":
            return redirect(stage_url(room["stage"], room_id, token))

        joined = set(room["joined"])
        mode = room["mode"]
        game_name = GAME_NAMES[mode]
        invite_tokens = room["teams"].copy() if number == 1 else {}

    invites = []
    for invite_token, team_number in invite_tokens.items():
        if team_number == 1:
            continue
        link = url_for("lobby", room_id=room_id, token=invite_token, _external=True)
        invites.append({"number": team_number, "link": link, "qr": make_qr(link)})

    return render_page(
        "lobby", f"{game_name} Lobby",
        number=number, count=count, joined=joined, invites=invites, error=error,
        mode=mode, board_sizes=SIZES,
        status_url=url_for("room_status", room_id=room_id, token=token),
    )


@app.route("/room/<room_id>/<token>/name", methods=["GET", "POST"])
def name_page(room_id, token):
    error = None

    with room_lock:
        room, number = get_team(room_id, token)

        if number not in room["joined"]:
            return redirect(stage_url("lobby", room_id, token), code=303)
        if room["stage"] != "naming":
            return redirect(stage_url(room["stage"], room_id, token), code=303)

        count = len(room["teams"])

        if request.method == "POST":
            if number in room["names"]:
                return redirect(stage_url("naming", room_id, token), code=303)

            name = request.form.get("team_name", "").strip()
            if 1 <= len(name) <= 30:
                room["names"][number] = name
                if len(room["names"]) == count:
                    room["stage"] = "reveal"
                return redirect(stage_url(room["stage"], room_id, token), code=303)

            error = "Enter a team name between 1 and 30 characters."

        submitted = number in room["names"]
        ready_count = len(room["names"])

    return render_page(
        "naming", "Choose your team name", number=number, count=count,
        submitted=submitted, ready_count=ready_count, error=error,
        status_url=url_for("room_status", room_id=room_id, token=token),
    )


@app.get("/room/<room_id>/<token>/reveal")
def reveal(room_id, token):
    with room_lock:
        room, number = get_team(room_id, token)

        if number not in room["joined"]:
            return redirect(stage_url("lobby", room_id, token))
        if room["stage"] != "reveal":
            return redirect(stage_url(room["stage"], room_id, token))

        names = sorted(room["names"].items())

        if room["mode"] == "guess":
            return redirect(url_for("guess_play", room_id=room_id, token=token))
        if room["mode"] == "quiz":
            return redirect(url_for("quiz_page", room_id=room_id, token=token))
        if room["mode"] == "xo":
            return redirect(url_for("xo_page", room_id=room_id, token=token))

    return render_page("reveal", "All teams are ready", names=names)


@app.get("/room/<room_id>/<token>/status")
def room_status(room_id, token):
    with room_lock:
        room, number = get_team(room_id, token)
        if number not in room["joined"]:
            abort(403)

        stage = room["stage"]
        return jsonify(
            stage=stage,
            joined=sorted(room["joined"]),
            count=len(room["teams"]),
            ready_count=len(room["names"]),
            next_url=stage_url(stage, room_id, token),
        )


@app.post("/quiz/solo")
def solo_quiz():
    room_id, token = secrets.token_urlsafe(16), secrets.token_urlsafe(16)
    with room_lock:
        rooms[room_id] = {
            "mode": "quiz", "stage": "reveal", "joined": {1},
            "teams": {token: 1}, "names": {1: "You"},
            "quiz": Quiz(["You"], solo=True),
        }
    return redirect(url_for("quiz_page", room_id=room_id, token=token), code=303)


def get_quiz_room(room_id, token):
    room, number = get_team(room_id, token)
    if room["mode"] != "quiz" or room["stage"] != "reveal" or number not in room["joined"]:
        abort(403)
    return room, number - 1


@app.get("/quiz/<room_id>/<token>")
def quiz_page(room_id, token):
    with room_lock:
        get_quiz_room(room_id, token)
    return render_template("quiz.html", state_url=url_for("quiz_state", room_id=room_id, token=token))


@app.route("/quiz/<room_id>/<token>/state", methods=["GET", "POST"])
def quiz_state(room_id, token):
    with room_lock:
        room, team = get_quiz_room(room_id, token)
        if "quiz" not in room:
            room["quiz"] = Quiz([name for _, name in sorted(room["names"].items())])
        quiz = room["quiz"]
        now = monotonic()
        quiz.tick(now)
        if request.method == "POST":
            data = request.get_json(silent=True)
            if not isinstance(data, dict):
                abort(400)
            action = data.get("action")
            if action == "answer":
                quiz.answer(team, data.get("choice"), data.get("revision"), now)
            elif action == "next":
                if team != 0:
                    abort(403)
                if data.get("phase") == quiz.phase and data.get("revision") == quiz.revision(team):
                    quiz.next(now)
            else:
                abort(400)
        response = jsonify(quiz.view(team, now, request.args.get("lang", request.headers.get("X-Football-Language", "en"))))
        response.headers["Cache-Control"] = "no-store"
        return response


def xo_settings(team=False):
    def option(field, allowed, default):
        value = request.form.get(field, str(default))
        for item in allowed:
            if str(item) == value:
                return item
        abort(400, "Invalid X/O setting")
    settings = dict(size=option("board-size", SIZES, 3),
                    difficulty=option("difficulty", ("Easy", "Medium", "Hard"), "Medium"))
    if team:
        settings.update(best_of=option("series", (1, 3, 5), 1),
                        turn_seconds=option("turn", (30, 40, 50, 60), 30),
                        round_minutes=option("round", (0, 4, 5, 6), 0))
    return settings


@app.route("/xo/solo", methods=["GET", "POST"])
def solo_xo():
    if request.method == "GET":
        return render_page("solo-settings", "Solo X/O", board_sizes=SIZES)
    room_id, token = secrets.token_urlsafe(16), secrets.token_urlsafe(16)
    with room_lock:
        rooms[room_id] = {
            "mode": "xo", "stage": "reveal", "joined": {1},
            "teams": {token: 1}, "names": {1: "You"}, "xo": Match(["You"], solo=True, **xo_settings()),
        }
    return redirect(url_for("xo_page", room_id=room_id, token=token), code=303)


def get_xo_room(room_id, token):
    room, number = get_team(room_id, token)
    if room["mode"] != "xo" or room["stage"] != "reveal" or number not in room["joined"]:
        abort(403)
    return room, number - 1


def get_xo_match(room, now):
    if "xo" not in room:
        room["xo"] = Match([name for _, name in sorted(room["names"].items())], now=now, **room.get("xo_settings", {}))
    match = room["xo"]
    match.tick(now)
    if match.finished and not match.solo and not match.series_over:
        if match.continue_at is None:
            match.continue_at = now + 4
        elif now >= match.continue_at:
            room["xo"] = match = match.next_round(now)
    return match


@app.get("/xo/<room_id>/<token>")
def xo_page(room_id, token):
    with room_lock:
        room, team = get_xo_room(room_id, token)
        now = monotonic()
        match = get_xo_match(room, now)
        board = match.view(team, now)
        response = app.make_response(render_template(
            "xo.html", state_url=url_for("xo_state", room_id=room_id, token=token),
            board=board, player_directory=PLAYER_DIRECTORY,
        ))
    response.headers["Cache-Control"] = "no-store"
    return response


@app.route("/xo/<room_id>/<token>/state", methods=["GET", "POST"])
def xo_state(room_id, token):
    with room_lock:
        room, team = get_xo_room(room_id, token)
        now = monotonic()
        match = get_xo_match(room, now)
        message = ""
        if request.method == "POST":
            data = request.get_json(silent=True)
            if not isinstance(data, dict):
                abort(400)
            action = data.get("action")
            if data.get("revision") != match.revision:
                message = "The board has changed."
            elif action == "play":
                index, guess = data.get("cell"), data.get("guess")
                if type(index) is not int or not 0 <= index < len(match.cells) or not isinstance(guess, str) or not 1 <= len(guess.strip()) <= 80:
                    abort(400)
                message = match.play(team, index, guess, now)
            elif action in {"pass", "end"} and not match.solo:
                if match.finished or team != match.turn:
                    message = "It is not your turn."
                elif action == "pass":
                    match.advance(now, "Turn passed.")
                    message = match.notice
                else:
                    new_match = match.vote_to_end(team, now)
                    if new_match is not match:
                        message = "Both teams voted. New board."
                        new_match.notice = message
                    room["xo"] = match = new_match
            elif action == "reveal" and (match.solo or match.finished):
                match.revealed = True
                match.revision += 1
            elif (action == "restart" and match.solo) or (action == "next" and not match.solo and team == 0 and match.finished and not match.series_over):
                room["xo"] = match = match.next_round(now)
            else:
                abort(403)
        response = jsonify(**match.view(team, now), message=message)
        response.headers["Cache-Control"] = "no-store"
        return response


@app.post("/imposter")
def start_imposter():
    count = request.form.get("players", type=int)
    if count not in range(3, 21):
        abort(400, "Choose between 3 and 20 players.")
    token = secrets.token_urlsafe(24)
    with room_lock:
        imposter_rooms[token] = new_imposter_round(count)
    return redirect(url_for("imposter_page", token=token), code=303)


@app.route("/imposter/<token>", methods=["GET", "POST"])
def imposter_page(token):
    with room_lock:
        game = imposter_rooms.get(token)
        if game is None:
            abort(404, "This Imposter round is no longer available.")
        if request.method == "POST":
            if request.form.get("revision", type=int) == game["revision"]:
                imposter_rooms[token] = imposter_move(
                    game, request.form.get("action")
                )
            return redirect(url_for("imposter_page", token=token), code=303)
        show_secret = game["phase"] == "role" and game["player"] != game["imposter"]
        secret = ROSTER[game["secret"]] if show_secret else None
        response = app.make_response(render_template("imposter.html", game=game.copy(), secret=secret))
    response.headers["Cache-Control"] = "private, no-store, max-age=0"
    return response


def transfer_history():
    return read_history(request.cookies.get("transfer_seen", ""))


def guess_variant():
    variant = request.form.get("game", "clubs")
    if variant not in {"clubs", "transfer", "mystery"}:
        abort(400, "Select a Guess game.")
    return variant


@app.route("/guess/solo", methods=["GET", "POST"])
def guess_solo():
    if request.method == "GET":
        return render_page("guess-menu", "Guess")
    room_id, token = secrets.token_urlsafe(16), secrets.token_urlsafe(16)
    with room_lock:
        rooms[room_id] = {"mode": "guess", "variant": guess_variant(), "mystery_seen": request.cookies.get("mystery_seen", "").split("."), "history": transfer_history(), "stage": "reveal", "joined": {1},
                          "teams": {token: 1}, "names": {1: "You"}}
    return redirect(url_for("guess_play", room_id=room_id, token=token), code=303)


def guess_room(room_id, token):
    room, number = get_team(room_id, token)
    if room["mode"] != "guess" or room["stage"] != "reveal" or number not in room["joined"]:
        abort(403)
    if room.get("variant") == "mystery":
        if "mystery" not in room:
            room["mystery"] = MysteryRound(room["names"], room.get("mystery_seen", ()))
        return room["mystery"], number
    if "guess" not in room:
        room["guess"] = GuessRound(room["names"], room.get("variant", "clubs"), room.get("history", ()))
    return room["guess"], number


@app.get("/guess/<room_id>/<token>")
def guess_play(room_id, token):
    with room_lock:
        game, number = guess_room(room_id, token)
    if isinstance(game, MysteryRound):
        return render_template("mystery.html", host=number == 1, state_url=url_for("guess_state", room_id=room_id, token=token),
                               photo_url=url_for("mystery_photo", room_id=room_id, token=token),
                               directory={pid:[p["name"],p["ar"]] for pid,p in MYSTERY_PLAYERS.items()})
    return render_template("guess.html", clubs=sorted(CAREERS if game.transfer else CLUBS), host=number == 1,
                           transfer=game.transfer, arabic_names={k:v["ar"] for k,v in CAREERS.items()} if game.transfer else {},
                           state_url=url_for("guess_state", room_id=room_id, token=token))


@app.get("/guess/<room_id>/<token>/photo")
def mystery_photo(room_id, token):
    with room_lock:
        game, _ = guess_room(room_id, token)
        if not isinstance(game, MysteryRound) or request.args.get("round") != game.token:
            abort(404)
        response = send_from_directory(MYSTERY_ROOT / "mystery-photos", game.target + ".jpg", etag=False)
        response.headers["Cache-Control"] = "private, no-store"
        return response


def mystery_state(game, number):
    message = ""
    if request.method == "POST":
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            abort(400)
        if data.get("token") == game.token:
            if data.get("action") == "replay":
                if number != 1 or not game.finished():
                    abort(403)
                game.begin()
            else:
                message = game.guess(number, data.get("player"))
    response = jsonify(game.view(number), message)
    response.headers["Cache-Control"] = "no-store"
    if number == 1 and request.cookies.get("mystery_seen") != ".".join(game.seen):
        response.set_cookie("mystery_seen", ".".join(game.seen), max_age=31536000, httponly=True, samesite="Lax")
    return response


@app.route("/guess/<room_id>/<token>/state", methods=["GET", "POST"])
def guess_state(room_id, token):
    with room_lock:
        game, number = guess_room(room_id, token)
        if isinstance(game, MysteryRound):
            return mystery_state(game, number)
        now = monotonic()
        feedback = None
        if request.method == "POST":
            data = request.get_json()
            if not isinstance(data, dict):
                abort(400)
            if data.get("start"):
                if number != 1:
                    abort(403)
                game.start(now)
            else:
                feedback = game.answer(number, data, now)
        view = game.view(number, now)
        response = jsonify(view, feedback)
        if game.transfer and view["phase"] == "playing":
            history = transfer_history()
            clue_id = CAREER_IDS[game.deck[view["index"]][0]]
            if not history or history[-1] != clue_id:
                if len(history) == len(CAREERS):
                    history = []
                elif clue_id in history:
                    history.remove(clue_id)
                history.append(clue_id)
                response.set_cookie("transfer_seen", ".".join(history), max_age=31536000,
                                    httponly=True, samesite="Lax", path="/")
        response.headers["Cache-Control"] = "no-store"
        return response


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)